import{_ as i,o,c as t,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Crimson/SeaStore Meeting 2023-04-26","description":"","frontmatter":{"title":"Ceph Crimson/SeaStore Meeting 2023-04-26","date":"2023-04-26T00:00:00.000Z","updated":"2023-05-03T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH 算法","高可用性","可扩展性","对象存储","块存储","文件系统存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Crimson_SeaStore_Meeting_2023-04-26.md","filePath":"posts/2023/Ceph_Crimson_SeaStore_Meeting_2023-04-26.md","lastUpdated":1780460162000}'),l={name:"posts/2023/Ceph_Crimson_SeaStore_Meeting_2023-04-26.md"};function r(s,e,a,p,c,g){return o(),t("div",null,[...e[0]||(e[0]=[n('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间：</strong> 2023年4月26日</p><p><strong>参会人员：</strong> Rocky, Isaiah, June, Phil</p><p><strong>会议议题：</strong></p><ol><li>项目进展汇报</li><li>技术问题讨论</li><li>后续行动计划</li></ol><p><strong>会议内容：</strong></p><ol><li><p><strong>自我介绍：</strong></p><ul><li>June 加入 Hari 团队，参与 GitHub 命令相关工作。</li></ul></li><li><p><strong>项目进展：</strong></p><ul><li>Rocky 主要跟进 Cephalocon 后的代码审查工作。</li><li>Engine 报告了 mod core system 和 connection reference 的变更，感谢 Sam 的贡献。已审查并合并了 circular Journal space for random block manager，以及 mod core messenger 的多核 socket 接受和连接功能。单元测试已完成，当前挑战是确保内存分配正确。</li><li>Engine 提到 OSD 操作消息缓冲列表的跨云约束可能未正确执行，但未触发故障。</li><li>Engine 将因放假而跳过下一次会议。</li></ul></li><li><p><strong>技术讨论：</strong></p><ul><li>讨论了 buffer lists 使用 Atomic reference Counting 的性能问题，认为只要不频繁操作引用计数，可能不需要立即修复，建议进行性能分析。</li><li>讨论了 c-star allocator 的工作原理，指出在释放其他核心分配的内存时需要发送消息回其他核心，但确实有效。</li><li>讨论了 PR 中的 lva point 修改，建议在测试通过后尽快合并，以避免重构困难。</li><li>讨论了 debug 构建中的 get connection pipeline 问题，认为 debug 模式下的行为是正确的，应修复。</li><li>讨论了 SMP 设置为三的测试结果，建议通过 debug 输出检查核心运行情况。</li></ul></li></ol><p><strong>后续行动计划：</strong></p><ul><li>继续进行性能分析和代码审查。</li><li>修复 debug 构建中的 get connection pipeline 问题。</li><li>确保 PR 的测试通过后尽快合并。</li><li>通过 debug 输出检查 SMP 设置的正确性。</li></ul><p><strong>会议结束：</strong></p><ul><li>会议在确认无其他议题后结束，祝大家下周工作顺利。</li></ul><p><strong>备注：</strong></p><ul><li>会议保留了部分计算机科学/ceph 相关领域英文原文的关键词，如 Cephalocon, mod core system, connection reference, Atomic reference Counting 等。</li></ul>',13)])])}const d=i(l,[["render",r]]);export{u as __pageData,d as default};
